export interface DocumentSchema {
  id: string;
  sourceId: string;
  content: string;
  title?: string;
  position?: number;
  embedding?: number[]; // 384-dim for semantic search
  metadata?: {
    chunkIndex: number;
    totalChunks: number;
  };
}

