class ViaGentDatabase extends Dexie {
  constructor() {
    super('ViaGentDB');
    this.version(13).stores({
      // existing tables...
    });
  }
}

export const useRAGStore = create<RAGStoreState>()(
  persist(
    (set, get) => ({
      // State
      chunkingProgress: new Map(),
      // Actions
      chunkSource: async (sourceId, content, options) => { ... }
    }),
    {
      name: 'rag-state',
      storage: createJSONStorage(() => createDexieStorage(...)),
      partialize: (state) => ({
        // Convert Map to array for serialization
        chunkingProgress: Array.from(state.chunkingProgress.entries()),
      }),
      onRehydrateStorage: () => (state) => {
        // Convert array back to Map
        state.chunkingProgress = new Map(state.chunkingProgress);
      }
    }
  )
);

export class DocumentChunker {
