class EmbeddingService {
  async embedChunks(
    chunks: ChunkMetadata[],
    options?: EmbeddingOptions
  ): Promise<Map<string, EmbeddingVector>> {
    // Implementation with progress tracking
  }
}

generateEmbeddings: async (chunks, options) => {
  set({ loading: true, error: null });
  try {
    const results = await embeddingService.embedChunks(chunks, options);
    // Update state and persist
    set({ loading: false });
    return results;
  } catch (error) {
    set({ error, loading: false });
  }
}

async detectCapability(): Promise<EmbeddingMode> {
  if (navigator.gpu && await this.hasCachedModel()) {
    return 'local';
  } else if (this.hasApiKey()) {
    return 'cloud';
  } else {
    return 'keyword-only';
  }
}
